class Solution {
public:
 int minTime(int n, vector<vector<int>>& edges) {
  vector<vector<array<int,3>>> g(n);
  for(auto &e:edges) g[e[0]].push_back({e[1],e[2],e[3]});
  const long long INF=4e18; vector<long long>d(n,INF);d[0]=0;
  priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>>pq;pq.push({0,0});
  while(!pq.empty()) {auto [t,u]=pq.top();pq.pop();if(t!=d[u])continue;
   for(auto e:g[u]){long long depart=max(t,(long long)e[1]);if(depart>e[2])continue;
    if(depart+1<d[e[0]]){d[e[0]]=depart+1;pq.push({d[e[0]],e[0]});}}
  }
  return d[n-1]==INF?-1:(int)d[n-1];
 }
};
